function renderC(){
  const suggestions=["reading","focus","research","css","recipes","later"];
  widget.innerHTML='<div class="chipbox" id="cb">'+tags.map(chipHTML).join('')+
    '<input id="tinput" placeholder="Type a tag…"/></div>'+
