  widget.querySelectorAll(".sug").forEach(s=>s.onclick=()=>{ tags.push(s.dataset.s); renderC(); });
  widget.querySelectorAll(".x").forEach(x=>x.onclick=()=>{ tags=tags.filter(t=>t!==x.dataset.t); renderC(); });
}

