const USED_TAGS=["reading","focus","research","css","recipes","later","reference","reading-list","weekend-writing"];
let cTyped=(new URLSearchParams(location.search).get("typed")||"");
function renderC(){
  const q=cTyped.trim().toLowerCase();
  const matches=USED_TAGS.filter(s=>!tags.includes(s) && (q==="" ? false : s.toLowerCase().includes(q)));
  const exact=USED_TAGS.some(s=>s.toLowerCase()===q);
  let drop="";
  if(q){
    drop='<div class="suggest" id="drop">'+
      matches.map(s=>'<span class="sug" data-s="'+s+'">'+s+'</span>').join('')+
      (!exact ? '<span class="sug" data-new="1" style="border-style:solid;border-color:var(--accent);color:var(--accent);">+ Create “'+cTyped.trim()+'”</span>' : '')+
      '</div>';
  }
  widget.innerHTML='<div class="chipbox" id="cb">'+tags.map(chipHTML).join('')+
    '<input id="tinput" placeholder="Type a tag…" value="'+cTyped.replace(/"/g,'&quot;')+'"/></div>'+
    drop+
    '<div class="method-hint">Tags you\'ve used before are suggested as you type — pick one, or create a new tag. Click × to remove.</div>';
  const inp=document.getElementById("tinput");
  inp.focus();
  inp.addEventListener("input",()=>{ cTyped=inp.value; renderC(); });
  inp.addEventListener("keydown",e=>{ if(e.key==="Enter"){ e.preventDefault(); const v=inp.value.trim();
    if(v&&!tags.includes(v)){ tags.push(v);} cTyped=""; renderC(); } });
  widget.querySelectorAll(".sug").forEach(s=>s.onclick=()=>{ const v=s.dataset.new?cTyped.trim():s.dataset.s;
    if(v&&!tags.includes(v)) tags.push(v); cTyped=""; renderC(); });
  widget.querySelectorAll(".x").forEach(x=>x.onclick=()=>{ tags=tags.filter(t=>t!==x.dataset.t); renderC(); });
}

