// Extract the query functions by evaluating the relevant JS from the file is complex; re-implement inline mirror test.
const fs=require('fs');
let html=fs.readFileSync('prototypes/search.html','utf8');
let js=html.split('<script>')[1].split('</script>')[0];
// strip DOM-dependent tail (everything from 'const qEl=' onward) and browser-only bits
js=js.split('const qEl=')[0];
eval(js);
const cases=[
  ['#focus'],
  ['#rome'],
  ['"read later"'],
  ['rome (#article OR #book)'],
  ['rome NOT #book'],
  ['"OR"'],
  ['focus AND #reading'],
  ['columns OR trastevere'],
];
for(const [q] of cases){
  const tree=parse(tokenize(q));
  const hits=DATA.filter(b=>evalNode(tree,b)).map(b=>b.title);
  console.log(JSON.stringify(q),'=>',hits.length,'::',hits.join(' | '));
}
PY

