function positiveTerms(n,acc){ // collect terms to highlight (skip those under NOT)
  if(!n) return;
  if(n.op==='term'){ acc.push(n.v); return; }
  if(n.op==='and'||n.op==='or'){ positiveTerms(n.l,acc); positiveTerms(n.r,acc); }
  // n.op==='not' → skip its subtree
}

