function esc0(s){ return (s||"").replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
// Highlight only free-text (word/phrase) terms in ordinary text fields.
function hlText(text,words){ let out=esc(text);
  words.filter(Boolean).forEach(t=>{ const re=new RegExp('('+esc0(t)+')','ig'); out=out.replace(re,'<mark>$1</mark>'); });
  return out; }
// A tag pill is highlighted only when it is exactly what a #tag condition asked
// for, or when a free-text term appears within the tag name.
function hlTag(tag,words,tagNames){
  if(tagNames.some(tn=>tn.toLowerCase()===tag.toLowerCase())) return '<mark>'+esc(tag)+'</mark>';
  return hlText(tag,words);
}
function whereMatched(b,words,tagNames){ const w=[];
  const has=s=>words.some(t=>s.toLowerCase().includes(t.toLowerCase()));
  const tagHit=b.tags.some(tg=>tagNames.some(tn=>tn.toLowerCase()===tg.toLowerCase()) || words.some(t=>tg.toLowerCase().includes(t.toLowerCase())));
  if(has(b.title))w.push("title"); if(tagHit)w.push("tag");
  if(has(b.note))w.push("note"); if(has(b.desc))w.push("description"); if(has(b.url)||has(b.site))w.push("web address");
  return w; }

