let pendingDelete=null;
function confirmDelete(b){ pendingDelete=b;
  const ov=document.createElement("div"); ov.className="overlay"; ov.id="ov";
  ov.innerHTML='<div class="dialog">'+
    '<h3>🗑 Delete this bookmark permanently?</h3>'+
    '<p>You are about to permanently delete <span class="target">“'+b.title+'”</span>. '+
      'This cannot be undone — the bookmark, its tags and your note are removed for good.</p>'+
    '<div class="tip">Just want it out of your main list? Use <b>Archive</b> instead — that keeps it and can be restored anytime.</div>'+
    '<div class="dacts"><button class="btn-cancel" id="cx">Cancel</button>'+
      '<button class="btn-danger" id="cd">Delete permanently</button></div>'+
  '</div>';
  document.body.appendChild(ov);
  document.getElementById("cx").onclick=closeDialog;
  ov.onclick=e=>{ if(e.target===ov) closeDialog(); };
  document.getElementById("cd").onclick=()=>{ DATA=DATA.filter(x=>x.id!==pendingDelete.id); closeDialog(); render(); };
}
function closeDialog(){ const ov=document.getElementById("ov"); if(ov) ov.remove(); pendingDelete=null; }

