input.new_string:
function editHTML(b){
  return '<div class="card hit" id="editcard"><div class="title" style="color:var(--accent);font-size:12px;text-transform:uppercase;letter-spacing:.04em;">Editing existing bookmark</div>'+
    '<label style="font-size:12px;color:var(--muted);display:block;margin:10px 0 4px;">Title</label>'+
    '<input id="eTitle" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:9px 11px;font-size:14px;" value="'+(b.title.replace(/"/g,"&quot;"))+'"/>'+
    '<label style="font-size:12px;color:var(--muted);display:block;margin:10px 0 4px;">Link (web address)</label>'+
    '<input id="eUrl" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:9px 11px;font-size:13px;" value="'+(b.url.replace(/"/g,"&quot;"))+'"/>'+
    '<label style="font-size:12px;color:var(--muted);display:block;margin:10px 0 4px;">Description</label>'+
    '<input id="eDesc" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:9px 11px;font-size:14px;" value="'+((b.desc||"").replace(/"/g,"&quot;"))+'"/>'+
    '<label style="font-size:12px;color:var(--muted);display:block;margin:10px 0 4px;">Tags (comma separated)</label>'+
    '<input id="eTags" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:9px 11px;font-size:14px;" value="'+b.tags.join(", ")+'"/>'+
    '<label style="font-size:12px;color:var(--muted);display:block;margin:10px 0 4px;">Your note</label>'+
    '<textarea id="eNote" style="width:100%;border:1px solid var(--line);border-radius:8px;padding:9px 11px;font-size:14px;min-height:52px;font-family:inherit;">'+(b.note||"")+'</textarea>'+
    '<label style="font-size:12px;color:var(--muted);display:block;margin:10px 0 6px;">Reading status</label>'+
    '<div style="display:flex;gap:8px;">'+
      '<button class="mini estat" data-s="toread" style="border-color:'+(b.status==="toread"?"var(--accent)":"var(--line)")+';color:'+(b.status==="toread"?"var(--accent)":"var(--muted)")+';margin:0;">📖 To read</button>'+
      '<button class="mini estat" data-s="finished" style="border-color:'+(b.status==="finished"?"var(--green)":"var(--line)")+';color:'+(b.status==="finished"?"var(--green)":"var(--muted)")+';margin:0;">✓ Finished</button>'+
    '</div>'+
    '<div style="display:flex;gap:10px;margin-top:14px;">'+
      '<button id="eSave" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:14px;font-weight:600;cursor:pointer;">Save changes</button>'+
      '<button id="eCancel" style="background:#fff;border:1px solid var(--line);border-radius:8px;padding:9px 16px;font-size:14px;cursor:pointer;">Cancel</button>'+
    '</div></div>';
}
function render(hitId){
  if(editingId){
    const b=DATA.find(x=>x.id===editingId);
    listEl.innerHTML=DATA.map(x=> x.id===editingId? editHTML(x) : cardHTML(x)).join('');
    let chosen=b.status;
    listEl.querySelectorAll(".estat").forEach(el=>el.onclick=()=>{ chosen=el.dataset.s;
      listEl.querySelectorAll(".estat").forEach(x=>{ const on=x.dataset.s===chosen;
        x.style.borderColor=on?(chosen==="toread"?"var(--accent)":"var(--green)"):"var(--line)";
        x.style.color=on?(chosen==="toread"?"var(--accent)":"var(--green)"):"var(--muted)"; }); });
    document.getElementById("eCancel").onclick=()=>{ editingId=null; notice.style.display="none"; render(); };
    document.getElementById("eSave").onclick=()=>{
      b.title=document.getElementById("eTitle").value.trim()||b.title;
      b.url=document.getElementById("eUrl").value.trim()||b.url;
      b.desc=document.getElementById("eDesc").value.trim();
      b.tags=document.getElementById("eTags").value.split(",").map(s=>s.trim()).filter(Boolean);
      b.note=document.getElementById("eNote").value;
      b.status=chosen;
      editingId=null;
      notice.className="notice added"; notice.style.display="block";
      notice.innerHTML='Updated <b>“'+b.title+'”</b> — the existing bookmark was edited, not duplicated.';
      render(b.id);
    };
    document.getElementById("editcard").scrollIntoView({behavior:"smooth",block:"center"});
    return;
  }
  listEl.innerHTML=DATA.map(cardHTML).join('');
  if(hitId){ const el=document.getElementById("card-"+hitId); if(el){ el.classList.add("hit"); el.scrollIntoView({behavior:"smooth",block:"center"}); } }
}
function openEdit(id){ editingId=id; render(); }

