let nextId=4;
let editingId=null;
let editTags=[]; // working copy of tags while editing
let tagTyped="";
const USED_TAGS=["reading","focus","css","reference","recipes","tax","research","reading-list","weekend-writing","productivity","history"];
function mdToHtml(src){
  const lines=(src||"").split(/\n/); let out=""; let inList=false;
  const inline=s=>s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');
  for(let ln of lines){
    if(/^###\s+/.test(ln)){ if(inList){out+="</ul>";inList=false;} out+="<h3>"+inline(ln.replace(/^###\s+/,''))+"</h3>"; }
    else if(/^[-*]\s+/.test(ln)){ if(!inList){out+="<ul>";inList=true;} out+="<li>"+inline(ln.replace(/^[-*]\s+/,''))+"</li>"; }
    else if(ln.trim()===""){ if(inList){out+="</ul>";inList=false;} }
    else { if(inList){out+="</ul>";inList=false;} out+="<p>"+inline(ln)+"</p>"; }
  }
  if(inList)out+="</ul>"; return out;
}

