function editHTML(b){
  return '<div class="card hit" id="editcard">'+
    '<div class="title" style="color:var(--accent);font-size:12px;text-transform:uppercase;letter-spacing:.04em;">Editing existing bookmark</div>'+
    '<label class="fl">Title</label><input id="eTitle" class="ein" value="'+(b.title.replace(/"/g,"&quot;"))+'"/>'+
    '<label class="fl">Link (web address)</label><input id="eUrl" class="ein" value="'+(b.url.replace(/"/g,"&quot;"))+'"/>'+
    '<label class="fl">Description</label><input id="eDesc" class="ein" value="'+((b.desc||"").replace(/"/g,"&quot;"))+'"/>'+
    '<label class="fl">Tags</label><div id="tagMount"></div>'+
    '<label class="fl">Your note <span style="font-weight:400;color:#9aa2ad;">— why you saved it</span></label>'+
    '<div class="noteedit"><div class="col"><div class="plabel">You type</div>'+
      '<textarea id="eNote">'+(b.note||"").replace(/</g,"&lt;")+'</textarea></div>'+
      '<div class="col"><div class="plabel">Live preview</div><div class="pv" id="eNotePv"></div></div></div>'+
    '<label class="fl">Reading status</label>'+
    '<div style="display:flex;gap:8px;">'+
      '<button class="mini estat" data-s="toread" style="margin:0;">📖 To read</button>'+
      '<button class="mini estat" data-s="finished" style="margin:0;">✓ Finished</button>'+
    '</div>'+
    '<div style="display:flex;gap:10px;margin-top:14px;">'+
      '<button id="eSave" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:14px;font-weight:600;cursor:pointer;">Save changes</button>'+
      '<button id="eCancel" style="background:#fff;border:1px solid var(--line);border-radius:8px;padding:9px 16px;font-size:14px;cursor:pointer;">Cancel</button>'+
    '</div></div>';
}
function renderTagWidget(){
  const mount=document.getElementById("tagMount"); if(!mount) return;
  const q=tagTyped.trim().toLowerCase();
  const matches=USED_TAGS.filter(s=>!editTags.includes(s) && q!=="" && s.toLowerCase().includes(q));
  const exact=USED_TAGS.some(s=>s.toLowerCase()===q);
  let drop="";
  if(q){ drop='<div class="suggest">'+matches.map(s=>'<span class="sug" data-s="'+s+'">'+s+'</span>').join('')+
    (!exact?'<span class="sug newtag" data-new="1">+ Create “'+tagTyped.trim()+'”</span>':'')+'</div>'; }
  mount.innerHTML='<div class="chipbox">'+editTags.map(t=>'<span class="tchip">'+t+'<span class="x" data-x="'+t+'">×</span></span>').join('')+
    '<input id="tagInput" placeholder="Type a tag…" value="'+tagTyped.replace(/"/g,"&quot;")+'"/></div>'+drop+
    '<div style="font-size:12px;color:var(--muted);margin-top:6px;">Tags you\'ve used before are suggested as you type — pick one or create a new tag.</div>';
  const inp=document.getElementById("tagInput"); inp.focus();
  inp.setSelectionRange(inp.value.length,inp.value.length);
  inp.oninput=()=>{ tagTyped=inp.value; renderTagWidget(); };
  inp.onkeydown=e=>{ if(e.key==="Enter"){ e.preventDefault(); const v=inp.value.trim(); if(v&&!editTags.includes(v)) editTags.push(v); tagTyped=""; renderTagWidget(); } };
  mount.querySelectorAll(".sug").forEach(s=>s.onclick=()=>{ const v=s.dataset.new?tagTyped.trim():s.dataset.s; if(v&&!editTags.includes(v)) editTags.push(v); tagTyped=""; renderTagWidget(); });
  mount.querySelectorAll("[data-x]").forEach(x=>x.onclick=()=>{ editTags=editTags.filter(t=>t!==x.dataset.x); renderTagWidget(); });
}
function render(hitId){
  if(editingId){
    const b=DATA.find(x=>x.id===editingId);
    editTags=editTags._for===b.id?editTags:Object.assign([...b.tags],{_for:b.id});
    listEl.innerHTML=DATA.map(x=> x.id===editingId? editHTML(x) : cardHTML(x)).join('');
    renderTagWidget();
    const nt=document.getElementById("eNote"), pv=document.getElementById("eNotePv");
    const upd=()=>pv.innerHTML=mdToHtml(nt.value); nt.oninput=upd; upd();
    let chosen=b.status;
    const paint=()=>listEl.querySelectorAll(".estat").forEach(x=>{ const on=x.dataset.s===chosen;
      x.style.borderColor=on?(chosen==="toread"?"var(--accent)":"var(--green)"):"var(--line)";
      x.style.color=on?(chosen==="toread"?"var(--accent)":"var(--green)"):"var(--muted)"; });
    listEl.querySelectorAll(".estat").forEach(el=>el.onclick=()=>{ chosen=el.dataset.s; paint(); }); paint();
    document.getElementById("eCancel").onclick=()=>{ editingId=null; editTags=[]; notice.style.display="none"; render(); };
    document.getElementById("eSave").onclick=()=>{
      b.title=document.getElementById("eTitle").value.trim()||b.title;
      b.url=document.getElementById("eUrl").value.trim()||b.url;
      b.desc=document.getElementById("eDesc").value.trim();
      b.tags=[...editTags]; b.note=document.getElementById("eNote").value; b.status=chosen;
      editingId=null; editTags=[];
      notice.className="notice added"; notice.style.display="block";
      notice.innerHTML='Updated <b>“'+b.title+'”</b> — the existing bookmark was edited, not duplicated.';
      render(b.id);
    };
    document.getElementById("editcard").scrollIntoView({behavior:"smooth",block:"center"});
    return;
