.saver input:focus { border-color:var(--accent); }
.saver button { background:var(--accent); color:#fff; border:none; border-radius:8px; padding:9px 18px; font-weight:600; cursor:pointer; }
.topactions { display:flex; gap:8px; }
.ghost { background:#fff; border:1px solid var(--line); border-radius:8px; padding:8px 12px; font-size:.85rem; cursor:pointer; color:var(--ink); }
.ghost:hover { background:#f0f2f6; }

.body { display:grid; grid-template-columns:230px 1fr; gap:0; max-width:1160px; margin:0 auto; }
@media(max-width:760px){ .body{ grid-template-columns:1fr; } .sidebar{ display:none; } }

/* sidebar */
.sidebar { padding:18px 14px; border-right:1px solid var(--line); min-height:calc(100vh - 58px); }
.sidebar h2 { font-size:.72rem; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:0 0 8px; }
.collhead { display:flex; align-items:center; justify-content:space-between; margin-top:18px; }
.linkbtn { background:none; border:none; color:var(--accent); cursor:pointer; font-size:.8rem; font-weight:600; }
.nav { display:flex; flex-direction:column; gap:3px; margin-bottom:6px; }
.nav button { text-align:left; border:none; background:none; border-radius:8px; padding:8px 10px; font-size:.9rem; cursor:pointer; color:var(--ink); display:flex; justify-content:space-between; align-items:center; gap:8px; }
.nav button:hover { background:#eef1f5; }
.nav button.active { background:#eef4ff; color:var(--accent); font-weight:600; }
.nav button .cnt { color:var(--muted); font-size:.78rem; font-weight:400; }
.nav button.active .cnt { color:var(--accent); }
.nav .collitem { position:relative; }
.nav .collitem .sub { font-size:.72rem; color:var(--muted); font-weight:400; display:block; }

/* main */
.main { padding:18px 22px; min-width:0; }
.searchrow { display:flex; gap:12px; align-items:center; }
.searchbox { position:relative; flex:1; }
.searchbox input { width:100%; border:1px solid var(--line); border-radius:10px; padding:11px 34px 11px 38px; font-size:.95rem; outline:none; background:#fff; }
.searchbox input:focus { border-color:var(--accent); }
.searchbox .mag { position:absolute; left:13px; top:50%; transform:translateY(-50%); color:var(--muted); }
.clearbtn { position:absolute; right:8px; top:50%; transform:translateY(-50%); border:none; background:none; color:var(--muted); cursor:pointer; font-size:.9rem; }
.sortwrap { display:flex; align-items:center; gap:7px; }
.sortwrap label { font-size:.85rem; color:var(--muted); }
select { border:1px solid var(--line); border-radius:8px; padding:8px 10px; font-size:.85rem; background:#fff; color:var(--ink); cursor:pointer; }
.tips { font-size:.75rem; color:var(--muted); margin:8px 2px 0; }
.toolbar { display:flex; align-items:center; justify-content:space-between; margin:14px 2px 6px; gap:10px; }
.count { font-size:.85rem; color:var(--muted); }
.count b { color:var(--ink); }
.selall { font-size:.82rem; color:var(--muted); display:flex; align-items:center; gap:6px; cursor:pointer; }
.matchbanner { background:#fff8e6; border:1px solid #f0dca8; color:#7a5a12; border-radius:9px; padding:9px 13px; font-size:.85rem; margin-bottom:10px; display:flex; gap:10px; align-items:center; flex-wrap:wrap; }
.matchbanner .link { color:var(--accent); cursor:pointer; font-weight:600; }

/* list + cards */
.list { display:flex; flex-direction:column; }
body[data-density="comfortable"] .list { gap:14px; }
body[data-density="compact"] .list { gap:7px; }
.card { background:var(--card); border:1px solid var(--line); border-radius:12px; overflow:hidden; display:flex; }
.card.sel { border-color:var(--accent); box-shadow:0 0 0 2px rgba(47,109,246,.16); }
.card .check { padding:14px 0 0 14px; }
.card .check input { width:17px; height:17px; cursor:pointer; }
.card .inner { flex:1; min-width:0; }
.card .preview { height:150px; background-size:cover; background-position:center center; background-color:#eef1f5; cursor:pointer; position:relative; }
.card .preview.ph { display:flex; align-items:center; justify-content:center; color:#9aa2ad; font-size:.8rem; font-weight:600; background:repeating-linear-gradient(45deg,#eef0f3,#eef0f3 12px,#e7eaee 12px,#e7eaee 24px); cursor:default; }
body[data-density="compact"] .card .preview { display:none; }
.card .cbody { padding:13px 16px; position:relative; }
body[data-density="compact"] .card .cbody { padding:9px 12px; }
.card .title { font-size:1.02rem; font-weight:600; line-height:1.34; margin:0 0 4px; padding-right:150px; }
.card a.title-link { color:var(--ink); text-decoration:none; cursor:pointer; }
.card a.title-link:hover { color:var(--accent); text-decoration:underline; }
.card .desc { font-size:.85rem; color:#4a5260; line-height:1.5; margin:0 0 9px;
  display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; }
body[data-density="compact"] .card .desc { display:none; }
.card .note { font-size:.82rem; color:#5a5030; background:#fbf6e9; border-left:3px solid #e5c96b; padding:8px 11px; border-radius:0 6px 6px 0; margin:0 0 9px; }
body[data-density="compact"] .card .note { display:none; }
.card .note h3 { font-size:.92rem; margin:.2em 0 .35em; } .card .note ul { margin:.2em 0; padding-left:18px; } .card .note a { color:var(--accent); }
.card .tags { display:flex; flex-wrap:wrap; gap:6px; margin:0 0 9px; }
.chip { background:#e7f0ff; color:#245; border-radius:999px; padding:2px 10px; font-size:.76rem; cursor:pointer; border:none; }
.chip:hover { background:#d4e5ff; }
.card .meta { display:flex; align-items:center; gap:8px; color:var(--muted); font-size:.8rem; flex-wrap:wrap; }
.card .fav { width:16px; height:16px; border-radius:4px; object-fit:cover; background:#dfe6f5; }
.badge { font-size:.68rem; font-weight:700; border-radius:999px; padding:2px 8px; }
.badge.toread { background:#eaf1fe; color:var(--accent); } .badge.finished { background:#e5f6ec; color:var(--green); } .badge.archived { background:#efeadd; color:#8a7726; }
.card a.urllink { color:var(--muted); font-size:.76rem; text-decoration:none; word-break:break-all; }
.card a.urllink:hover { color:var(--accent); text-decoration:underline; }
.card .rowacts { display:flex; gap:7px; margin-top:11px; flex-wrap:wrap; }
.act { border:1px solid var(--line); background:#fff; border-radius:8px; padding:6px 11px; font-size:.78rem; cursor:pointer; color:var(--ink); }
.act:hover { background:#f0f2f6; }
.act.open { border-color:#bcd0f7; color:var(--accent); font-weight:600; }
.act.danger { color:var(--danger); border-color:#ecc7c2; }
.copybadge { font-size:.7rem; padding:2px 8px; border-radius:999px; }
.copybadge.saved { background:#e5f6ec; color:var(--green); } .copybadge.pending { background:#eef1f5; color:var(--muted); } .copybadge.failed { background:#fdecea; color:var(--danger); }

.loadingmore { text-align:center; color:var(--muted); font-size:.85rem; padding:18px; }
.empty { text-align:center; color:var(--muted); padding:52px 20px; }
.empty .ic { font-size:2.4rem; display:block; margin-bottom:10px; }
.empty h3 { color:var(--ink); margin:0 0 6px; }

.spin { width:14px; height:14px; border:2px solid #cfd6df; border-top-color:var(--accent); border-radius:50%; display:inline-block; animation:spin 1s linear infinite; vertical-align:-2px; }
@keyframes spin { to { transform:rotate(360deg); } }

/* bulk bar */
.bulkbar { position:fixed; left:50%; bottom:20px; transform:translateX(-50%); background:#1e2430; color:#fff; border-radius:14px; padding:9px 11px; display:flex; align-items:center; gap:6px; box-shadow:0 12px 40px rgba(0,0,0,.35); flex-wrap:wrap; z-index:40; max-width:94vw; }
.bulkbar .nsel { font-weight:700; padding:0 8px; font-size:.85rem; white-space:nowrap; }
.bulkbar button { background:#2b3340; color:#fff; border:1px solid #3a4350; border-radius:8px; padding:8px 11px; font-size:.78rem; cursor:pointer; white-space:nowrap; }
.bulkbar button:hover { background:#38414f; }
.bulkbar button.danger { color:#ffb4ab; border-color:#5a2b28; }
.bulkbar button.x { background:none; border:none; color:#9aa2ad; font-size:1rem; }

/* modal */
.overlay { position:fixed; inset:0; background:rgba(20,25,35,.5); display:flex; align-items:flex-start; justify-content:center; padding:40px 16px; z-index:50; overflow:auto; }
.modal { background:#fff; border-radius:14px; width:100%; max-width:620px; box-shadow:0 24px 70px rgba(0,0,0,.3); }
.modal.wide { max-width:720px; }
.modal .mhead { padding:16px 20px; border-bottom:1px solid var(--line); display:flex; justify-content:space-between; align-items:center; }
.modal .mhead h3 { margin:0; font-size:1.05rem; }
.modal .mhead .x { border:none; background:none; font-size:1.2rem; cursor:pointer; color:var(--muted); }
.modal .mbody { padding:18px 20px; }
.modal .banner { height:150px; background-size:cover; background-position:center; border-radius:10px; margin-bottom:14px; }
.modal .banner.ph { display:flex; align-items:center; justify-content:center; color:#9aa2ad; font-size:.85rem; font-weight:600; background:repeating-linear-gradient(45deg,#eef0f3,#eef0f3 12px,#e7eaee 12px,#e7eaee 24px); }
.warnbar { background:#fdf5e6; border:1px solid #f0dcb0; color:var(--warn); border-radius:9px; padding:10px 13px; font-size:.85rem; margin-bottom:12px; display:flex; gap:8px; }
.fl { display:block; font-size:.78rem; color:var(--muted); margin:12px 0 5px; font-weight:600; }
.fl:first-child { margin-top:0; }
.in { width:100%; border:1px solid var(--line); border-radius:8px; padding:9px 11px; font-size:.9rem; font-family:inherit; outline:none; }
.in:focus { border-color:var(--accent); }
textarea.in { resize:vertical; min-height:60px; }
.chipbox { display:flex; flex-wrap:wrap; gap:6px; align-items:center; border:1px solid var(--line); border-radius:8px; padding:7px 9px; }
.chipbox:focus-within { border-color:var(--accent); }
.tchip { display:inline-flex; align-items:center; gap:6px; background:#eef2f8; border-radius:999px; padding:4px 10px; font-size:.82rem; }
.tchip .x { cursor:pointer; font-weight:700; opacity:.7; }
.chipbox input { border:none; outline:none; flex:1; min-width:110px; font-size:.88rem; padding:3px; }
.suggest { display:flex; flex-wrap:wrap; gap:6px; margin-top:6px; }
.sug { background:#fff; border:1px dashed #c4cbd6; color:#54607a; border-radius:999px; padding:3px 10px; font-size:.8rem; cursor:pointer; }
.sug.new { border-style:solid; border-color:var(--accent); color:var(--accent); }
.noteedit { display:flex; gap:10px; }
.noteedit .col { flex:1; min-width:0; }
.noteedit .plabel { font-size:.68rem; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin-bottom:5px; font-weight:700; }
.noteedit textarea { min-height:110px; font-family:ui-monospace,Menlo,Consolas,monospace; font-size:.82rem; }
.noteedit .pv { border:1px solid var(--line); border-radius:8px; padding:10px 12px; background:#fbfcfd; font-size:.88rem; min-height:110px; }
.noteedit .pv h3 { font-size:.95rem; margin:.2em 0 .35em; } .noteedit .pv ul { margin:.2em 0; padding-left:18px; } .noteedit .pv a { color:var(--accent); }
.choice { display:flex; gap:10px; }
.choice button { flex:1; border:1px solid var(--line); background:#fff; border-radius:9px; padding:10px; font-size:.88rem; cursor:pointer; color:var(--ink); }
.choice button.sel.toread { border-color:var(--accent); background:#eef4ff; color:var(--accent); font-weight:600; }
.choice button.sel.finished { border-color:#bfe3cd; background:#e9f8ef; color:var(--green); font-weight:600; }
.mactions { display:flex; gap:10px; margin-top:18px; }
.btn { border:1px solid var(--line); background:#fff; border-radius:8px; padding:9px 16px; font-size:.88rem; cursor:pointer; color:var(--ink); }
.btn.primary { background:var(--accent); color:#fff; border-color:var(--accent); font-weight:600; }
.btn.danger { background:var(--danger); color:#fff; border:none; font-weight:600; }
.hintline { font-size:.78rem; color:var(--muted); margin-top:8px; }
.panelbox { border:1px solid var(--line); border-radius:10px; padding:13px 15px; margin-top:14px; }
.panelbox h4 { margin:0 0 8px; font-size:.92rem; }
.statusline { display:flex; align-items:center; gap:8px; font-size:.85rem; margin-bottom:10px; }
.dot { width:9px; height:9px; border-radius:50%; } .dot.ok{background:var(--green);} .dot.pending{background:var(--accent);} .dot.failed{background:var(--danger);} .dot.none{background:#c4cbd6;}
.scope { display:flex; gap:8px; flex-wrap:wrap; margin-top:6px; }
.scope label { font-size:.85rem; display:flex; gap:6px; align-items:center; border:1px solid var(--line); border-radius:8px; padding:7px 11px; cursor:pointer; }
.drop { border:1.5px dashed #c4cbd6; border-radius:10px; padding:20px; text-align:center; color:var(--muted); font-size:.85rem; }
.opt { display:flex; align-items:center; gap:9px; font-size:.85rem; margin:10px 0 0; }
.progress { height:9px; background:#eef1f5; border-radius:999px; overflow:hidden; margin:10px 0 6px; }
.progress > span { display:block; height:100%; background:var(--accent); }

/* toast */
.toastroot { position:fixed; top:16px; left:50%; transform:translateX(-50%); z-index:80; display:flex; flex-direction:column; gap:8px; align-items:center; }
.toast { background:#1e2430; color:#fff; padding:9px 15px; border-radius:8px; font-size:.85rem; box-shadow:0 8px 24px rgba(0,0,0,.25); }
.toast.good { background:#1c7a4d; } .toast.bad { background:var(--danger); }

