  const m = openModal(`<div class="mhead"><h3>${esc(b.title)}</h3><button class="x" data-close>×</button></div>
    <div class="mbody"><div class="meta" style="color:var(--muted);font-size:.8rem;margin-bottom:8px">${esc(b.url)}</div>
