/* ---------- import / export (SCN-015) ---------- */
function openImportExport() {
  const m = openModal(`<div class="mhead"><h3>Import &amp; export</h3><button class="x" data-close>×</button></div>
    <div class="mbody">
      <div class="panelbox"><h4>⬆ Import bookmarks</h4>
