}
function renderBulkBar() {
  const n = selCount(); const bar = $('#bulkBar');
  if (n === 0) { bar.hidden = true; bar.innerHTML = ''; return; }
  bar.hidden = false;
  bar.innerHTML = `<span class="nsel">${n} selected</span>
